<?php
if (!isset($activity, $user) || !function_exists('require_login')) { http_response_code(404); exit; }
require_login();
?>
<section class="card spaced"><div class="section-heading"><h2><?= e(t('Repayment schedule')) ?></h2><span class="count-pill"><?= e(t('Monthly installments')) ?></span></div>
<?php if (!$activity['schedule']): ?><div class="empty"><p><?= e(t('Your schedule will appear after funds are disbursed.')) ?></p></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th><?= e(t('Installment')) ?></th><th><?= e(t('Due date')) ?></th><th><?= e(t('Principal')) ?></th><th><?= e(t('Interest')) ?></th><th><?= e(t('Penalty')) ?></th><th><?= e(t('Paid')) ?></th><th><?= e(t('Remaining')) ?></th><th><?= e(t('Status')) ?></th></tr></thead><tbody><?php foreach ($activity['schedule'] as $row): ?><tr><td>#<?= e($row['installment_number']) ?></td><td><?= e(format_date($row['due_date'])) ?></td><?php foreach (['principal_due_rwf','interest_due_rwf','penalty_due_rwf','amount_paid_rwf'] as $field): ?><td class="amount"><?= e(money($row[$field])) ?></td><?php endforeach; ?><td class="amount"><?= e(money((float) $row['principal_due_rwf'] + (float) $row['interest_due_rwf'] + (float) $row['penalty_due_rwf'] - (float) $row['amount_paid_rwf'])) ?></td><td><?= status_badge($row['display_status']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="card spaced"><div class="section-heading"><h2><?= e(t('Payment history')) ?></h2><span class="count-pill"><?= e(t('Confirmed payments')) ?></span></div><?php if (!$activity['payments']): ?><div class="empty"><p><?= e(t('No confirmed payments yet.')) ?></p></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th><?= e(t('Receipt')) ?></th><th><?= e(t('Date & method')) ?></th><th><?= e(t('Amount paid')) ?></th><th><?= e(t('Balance after payment')) ?></th><th></th></tr></thead><tbody><?php foreach ($activity['payments'] as $row): ?><tr><td><strong><?= e($row['receipt_number']) ?></strong><span class="cell-note"><?= e($row['reference_code']) ?></span></td><td><?= e(format_date($row['payment_date'])) ?><span class="cell-note"><?= e(enum_label($row['payment_method'])) ?></span></td><td class="amount"><?= e(money($row['amount_paid_rwf'])) ?></td><td class="amount"><?= e(money($row['balance_after_rwf'])) ?></td><td><a href="<?= e(app_url('portal/receipt.php?id=' . $row['payment_id'])) ?>"><?= e(t('Receipt ↗')) ?></a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php if ($activity['submissions']): ?><section class="card spaced"><h2><?= e(t('Submitted payment details')) ?></h2><div class="table-wrap"><table class="data-table"><thead><tr><th><?= e(t('Reference')) ?></th><th><?= e(t('Payment date')) ?></th><th><?= e(t('Amount')) ?></th><th><?= e(t('Status')) ?></th><th><?= e(t('Review note')) ?></th></tr></thead><tbody><?php foreach ($activity['submissions'] as $row): ?><tr><td><?= e($row['reference_code']) ?></td><td><?= e(format_date($row['payment_date'])) ?></td><td class="amount"><?= e(money($row['amount_rwf'])) ?></td><td><?= status_badge($row['status']) ?></td><td><?= e($row['review_notes'] ?? '—') ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<?php if ($activity['history']): ?><section class="card spaced"><h2><?= e(t('Loan status history')) ?></h2><ol class="timeline"><?php foreach ($activity['history'] as $row): ?><li><div><?= status_badge($row['new_status']) ?><span class="muted"><?= e(format_date($row['changed_at'], true)) ?></span></div><p><?= e(t($row['reason'] ?? '')) ?></p></li><?php endforeach; ?></ol></section><?php endif; ?>
